stages.source:
vec2 uv = fragCoord / iResolution.xy;
float brightness = uv.x;
fragColor = vec4(brightness, brightness, brightness, 1.0);

vec2 uv = fragCoord / iResolution.xy;
float lit = step(0.5, uv.x);
fragColor = vec4(lit, lit, lit, 1.0);

vec2 uv = fragCoord / iResolution.xy;
float edge = 0.5 + sin(iTime) * 0.35;
float lit = step(edge, uv.x);
fragColor = vec4(lit, lit, lit, 1.0);

vec2 uv = fragCoord / iResolution.xy;
float diagonal = (uv.x + uv.y) * 0.5;
float lit = step(0.5, diagonal);
fragColor = vec4(lit, lit, lit, 1.0);

vec2 uv = fragCoord / iResolution.xy;
float diagonal = (uv.x + uv.y) * 0.5;
float lit = step(0.5, diagonal);
fragColor = vec4(lit, lit, lit, 1.0);

vec2 uv = fragCoord / iResolution.xy;
float diagonal = (uv.x + uv.y) * 0.5;
float lit = smoothstep(0.48, 0.52, diagonal);
fragColor = vec4(lit, lit, lit, 1.0);

vec2 uv = fragCoord / iResolution.xy;
float diagonal = (uv.x + uv.y) * 0.5;
float lit = smoothstep(0.3, 0.7, diagonal);
fragColor = vec4(lit, lit, lit, 1.0);

vec2 uv = fragCoord / iResolution.xy;
float diagonal = (uv.x + uv.y) * 0.5;
float halfWidth = 0.02 + (sin(iTime) * 0.5 + 0.5) * 0.28;
float lit = smoothstep(0.5 - halfWidth, 0.5 + halfWidth, diagonal);
fragColor = vec4(lit, lit, lit, 1.0);

vec3 cool = vec3(0.31, 0.84, 1.0);
vec3 warm = vec3(1.0, 0.42, 0.42);
vec3 colour = mix(cool, warm, 0.5);
fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec3 cool = vec3(0.31, 0.84, 1.0);
vec3 warm = vec3(1.0, 0.42, 0.42);
vec3 colour = mix(cool, warm, uv.x);
fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec3 cool = vec3(0.31, 0.84, 1.0);
vec3 warm = vec3(1.0, 0.42, 0.42);
float factor = smoothstep(0.35, 0.65, uv.x);
vec3 colour = mix(cool, warm, factor);
fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec3 red = vec3(1.0, 0.0, 0.0);
vec3 green = vec3(0.0, 1.0, 0.0);
vec3 colour = mix(red, green, uv.x);
fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
float boosted = uv.x * 2.5;
fragColor = vec4(boosted, boosted, boosted, 1.0);

vec2 uv = fragCoord / iResolution.xy;
float boosted = clamp(uv.x * 2.5, 0.0, 1.0);
fragColor = vec4(boosted, boosted, boosted, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec3 cool = vec3(0.31, 0.84, 1.0);
vec3 warm = vec3(1.0, 0.42, 0.42);
float factor = uv.x * 2.5 - 0.6;
vec3 colour = mix(cool, warm, factor);
fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec3 cool = vec3(0.31, 0.84, 1.0);
vec3 warm = vec3(1.0, 0.42, 0.42);
float factor = clamp(uv.x * 2.5 - 0.6, 0.0, 1.0);
vec3 colour = mix(cool, warm, factor);
fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
float narrow = uv.x * 0.4 + 0.3;
fragColor = vec4(narrow, narrow, narrow, 1.0);

vec2 uv = fragCoord / iResolution.xy;
float inMin = 0.25;
float inMax = 0.75;
float t = (uv.x - inMin) / (inMax - inMin);
fragColor = vec4(t, t, t, 1.0);

vec2 uv = fragCoord / iResolution.xy;
float eased = pow(uv.x, 3.0);
fragColor = vec4(eased, eased, eased, 1.0);

vec2 uv = fragCoord / iResolution.xy;
float rise = pow(uv.x, 3.0);
float decay = exp(-uv.x * 4.0);
float upper = step(0.5, uv.y);
float eased = mix(rise, decay, upper);
fragColor = vec4(eased, eased, eased, 1.0);
